html[data-theme=dark].bgaext_bright .mf_item_back.mf_die_darken.mf_die_darken_3 {
  filter: grayscale(100%) brightness(0.9) var(--ext-bright);
}
html[data-theme=dark].bgaext_dark {
  /* background of the game (#b694c5 to silver) with a lower lightness */
  /* zones and title bar, too close to the dark background: an outline (no border, the zones have a fixed size) */
  /* the player zones have the color of the player (replaced by the generic .mf_zone background of game.less): the colors of the game with a lower lightness */
  /* reserve of cubes, on the background of the page: default (black) text color */
  /* popups of the game (help): white (90 %) with a lower lightness, and the dark text of the help */
  /* overflow: scroll in the game: useless horizontal scrollbar */
  /* white band of the messages flashed in the middle of the screen */
}
html[data-theme=dark].bgaext_dark body {
  background: linear-gradient(-25deg, hsl(281, 30%, 18%), hsl(0, 0%, 20%));
  background-position: top;
  background-repeat: repeat;
  background-size: 100vw;
}
