html[data-theme=dark].bgaext_dark #maingameview_menufooter {
  border: 1px solid var(--dark-40);
}
html[data-theme=dark].bgaext_dark #maingameview_menuheader {
  border-top: none;
  top: -1px;
}
html[data-theme=dark].bgaext_dark .log .stop-or-more-row .stop-or-more-stars .stop-or-more-amount,
html[data-theme=dark].bgaext_dark .log.die-modified-power9-log .die-modified-colon,
html[data-theme=dark].bgaext_dark .log.die-modified-power9-log .die-modified-arrow,
html[data-theme=dark].bgaext_dark .log .last-chance-row,
html[data-theme=dark].bgaext_dark .log .last-chance-row .last-chance-arrow,
html[data-theme=dark].bgaext_dark .log .start-token-row,
html[data-theme=dark].bgaext_dark .log .start-token-row .start-token-arrow,
html[data-theme=dark].bgaext_dark .log .grand-slam-row,
html[data-theme=dark].bgaext_dark .log .player-crashed-row,
html[data-theme=dark].bgaext_dark .log .game-end-row,
html[data-theme=dark].bgaext_dark .log .golden-die-row .golden-die-plus {
  color: var(--light-80);
}
html[data-theme=dark].bgaext_dark .log .log-arrow {
  color: var(--light-80);
  text-shadow: none;
}
html[data-theme=dark].bgaext_dark .log .player-crashed-row .fa-bomb {
  color: hsl(0, 100%, 55%);
}
html[data-theme=dark].bgaext_dark .log .grand-slam-row .grand-slam-title {
  color: hsl(38, 100%, 60%);
  text-shadow: 0 0 14px rgba(255, 196, 60, 0.5);
}
html[data-theme=dark].bgaext_dark #stop-button:not(.stop-button-finishing) {
  background: linear-gradient(#0bb76c, #24895d) !important;
  border: 1px solid #004d05 !important;
  color: #fff !important;
  box-shadow: none !important;
}
html[data-theme=dark].bgaext_dark #stop-button:not(.stop-button-finishing):hover {
  background: linear-gradient(#06ea87, #24895d) !important;
  color: #fff !important;
  box-shadow: none !important;
}
html[data-theme=dark].bgaext_dark #stop-button.stop-button-finishing {
  background: linear-gradient(#b6b70b, #898924) !important;
  border: 1px solid #00334d !important;
  color: #fff !important;
  box-shadow: none !important;
  text-shadow: none;
}
html[data-theme=dark].bgaext_dark #stop-button.stop-button-finishing:hover {
  background: linear-gradient(#eaea06, #898924) !important;
  color: #fff !important;
  box-shadow: none !important;
}
html[data-theme=dark].bgaext_dark .tooltip-wrapper {
  --bg-gradient-tooltip: linear-gradient(120deg, hsl(203, 50%, 14%), hsl(198, 40%, 20%));
  --bg-gradient-tooltip-connector: linear-gradient(-120deg, hsl(198, 40%, 20%), hsl(200, 50%, 14%));
  color: var(--light-80);
  outline-color: var(--light-50);
}
html[data-theme=dark].bgaext_dark .dijitTooltipContainer .tooltip-wrapper.power-reference {
  background-color: hsl(187, 81%, 18%) !important;
  color: var(--light-80);
}
html[data-theme=dark].bgaext_dark .dijitTooltipContainer .tooltip-wrapper.power-reference .power-reference-entry.highlighted-power-entry {
  background: hsl(187, 60%, 25%);
  border-color: hsl(187, 40%, 50%);
}
html[data-theme=dark].bgaext_dark .dijitTooltipContainer .tooltip-wrapper.power-reference .power-reference-entry.focused-power-entry {
  background: hsl(187, 60%, 30%);
  border-color: var(--light-80);
}
html[data-theme=dark].bgaext_dark .dijitTooltipContainer .tooltip-wrapper.power-reference .power-reference-column + .power-reference-column,
html[data-theme=dark].bgaext_dark .dijitTooltipContainer .tooltip-wrapper.power-reference .power-reference-hint {
  border-color: var(--light-50);
}
html[data-theme=dark].bgaext_dark .dijitTooltipContainer .tooltip-wrapper.power-reference .power-reference-balanced-columns {
  column-rule-color: var(--light-50);
}
html[data-theme=dark].bgaext_dark .tooltip-wrapper.power-reference.status-bar-power-tooltip {
  background: var(--bg-gradient-tooltip) !important;
}
html[data-theme=dark].bgaext_dark .tooltip-wrapper.power-reference.status-bar-power-tooltip .power-reference-entry.highlighted-power-entry {
  background: hsl(187, 81%, 18%);
  color: var(--light-80);
}
html[data-theme=dark].bgaext_dark .tundra .dijitTooltip:has(.tooltip-wrapper) .dijitTooltipConnector {
  filter: none;
}
html[data-theme=dark].bgaext_dark .tundra .dijitTooltip:has(.power-reference) .dijitTooltipConnector:after {
  background: hsl(187, 81%, 18%);
}
html[data-theme=dark].bgaext_dark .player-spotlight-overlay .player-spotlight-player,
html[data-theme=dark].bgaext_dark .player-spotlight-overlay .player-spotlight-tile,
html[data-theme=dark].bgaext_dark .player-spotlight-overlay.grand-slam-spotlight .grand-slam-name-pill {
  background-color: hsla(0, 0%, 15%, 0.92);
  color: var(--light-80);
}
html[data-theme=dark].bgaext_dark .end-game-score-container {
  background: linear-gradient(377deg, hsl(207, 65%, 20%) 27%, hsl(201, 70%, 35%) 110%);
  /* #a00000 with a higher lightness */
}
html[data-theme=dark].bgaext_dark .end-game-score-container table thead th.player-name-cell,
html[data-theme=dark].bgaext_dark .end-game-score-container table thead th.player-name-cell.jumping-text {
  background: hsl(197, 43%, 15%);
  text-shadow: none;
}
html[data-theme=dark].bgaext_dark .end-game-score-container table tbody td {
  background-color: hsla(41, 85%, 15%, 0.6);
  color: var(--light-80);
}
html[data-theme=dark].bgaext_dark .end-game-score-container table tbody tr.total-row td {
  background-color: hsl(46, 82%, 18%);
}
html[data-theme=dark].bgaext_dark .end-game-score-container table tbody tr.total-row td.row-label-cell {
  background-color: hsl(45, 77%, 25%);
  color: var(--light-80);
}
html[data-theme=dark].bgaext_dark .end-game-score-container table tbody td .cell-grand_slam {
  background: linear-gradient(135deg, hsl(48, 100%, 25%), hsl(45, 77%, 25%));
}
html[data-theme=dark].bgaext_dark .end-game-score-container table tbody td .cell-crashed .fa-bomb {
  color: hsl(0, 100%, 55%);
}
html[data-theme=dark].bgaext_dark .end-game-score-container table tbody td .cell-unfinished {
  color: var(--light-50);
}

snakesladders.css:
html[data-theme=dark].bgaext_dark {
  --ext-overall-color: #0008;
  --tile-light: var(--dark-20);
  --tile-alt: var(--dark-40);
  --accent-start: #0f5729;
  --accent-end: #052861;
}
html[data-theme=dark].bgaext_dark .board-container {
  color: var(--light-70);
}

wizardsgarden.css:
/* the drop shadows of the game are kept */
html[data-theme=dark].bgaext_bright .wg-seed {
  filter: drop-shadow(0 5px 5px rgba(0, 0, 0, 0.38)) var(--ext-bright);
}
html[data-theme=dark].bgaext_bright .wg-seed--preview {
  filter: drop-shadow(0 5px 6px rgba(0, 0, 0, 0.45)) var(--ext-bright);
}
html[data-theme=dark].bgaext_bright .wg-reserve-seed {
  filter: drop-shadow(0 1px 2px rgba(0, 0, 0, 0.4)) var(--ext-bright);
}
html[data-theme=dark].bgaext_bright .wg-board-color-picker__button {
  filter: var(--ext-bright);
}
html[data-theme=dark].bgaext_dark {
  /* gradient of the game (#f6f0d8, #d9cda9, #b8a477) with a lower lightness,
	   on the html tag: the body doesn't always cover the whole page (customBack keeps the light wood of BGA on the html tag) */
  background: radial-gradient(circle at top, hsl(48, 63%, 20%) 0, hsl(45, 39%, 16%) 48%, hsl(42, 31%, 12%) 100%);
}
html[data-theme=dark].bgaext_dark #ebd-body {
  background: none;
}
html[data-theme=dark].bgaext_dark .wg-tome-indicator {
  background: #3d2f10;
  color: #f3d98a;
  box-shadow: none;
}
